package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;
import net.officefloor.hq.app.history.History;

/** A named period on the sheet, from one date to another, both inclusive. A claim belongs to the
 *  period whose dates contain its due-by date, or to none. A closed period keeps the due-total it had when
 *  closed, and each person's carried figure and each pool member's cut, and its claims can no longer change, until a steward reopens it. A soft-closed period keeps
 *  its figures fixed the same way, but its claims can still change. */
@Entity
@EntityListeners(History.class)
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Moved on by each save, a change to its openings too, so the history keeps each change. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** Locked by a steward: it cannot be reopened until a steward unlocks it. */
    @Column(name = "locked", nullable = false)
    private boolean locked;

    /** The most OPEN or PENDING claims a person may have in the period; null for no cap. */
    @Column(name = "claim_cap")
    private Integer cap;

    @Column(name = "closed_total")
    private BigDecimal closedTotal;

    /** Each person's due-total for the period, fixed when it was closed, by person id; empty while open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", nullable = false)
    private Map<Long, BigDecimal> closedPersonTotals = new HashMap<>();

    /** Each person's carried figure for the period, fixed when it was closed, by person id; empty while open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "carried", nullable = false)
    private Map<Long, BigDecimal> closedPersonCarried = new HashMap<>();

    /** Each person's opening balance for the period, added to their carried figure for it, by person id; a
     *  person missing here has none. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_opening", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "opening", nullable = false)
    private Map<Long, BigDecimal> openings = new HashMap<>();

    /** Each pool member's cut for the period, fixed when it was closed, by member key (see
     *  {@code PoolController.memberKey}); a member missing here had none; empty while open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_pool_cut", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "member_key")
    @Column(name = "cut", nullable = false)
    private Map<String, BigDecimal> closedCuts = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this(sheetId, name, fromDate, toDate, null);
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate, Integer cap) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
        this.cap = cap;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** The most OPEN or PENDING claims a person may have in the period; null for no cap. */
    public Integer getCap() {
        return cap;
    }

    public boolean isClosed() {
        return closed;
    }

    /** Soft-closed: its figures are fixed, but its claims can still change. */
    public boolean isSoftClosed() {
        return softClosed;
    }

    /** Locked by a steward: it cannot be reopened until a steward unlocks it. */
    public boolean isLocked() {
        return locked;
    }

    public void setLocked(boolean locked) {
        this.locked = locked;
    }

    /** The due-total fixed when it was closed or soft-closed; null while open. */
    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    /** Each person's due-total fixed when it was closed, by person id; empty while open. */
    public Map<Long, BigDecimal> getClosedPersonTotals() {
        return closedPersonTotals;
    }

    /** Each person's carried figure fixed when it was closed, by person id; empty while open. */
    public Map<Long, BigDecimal> getClosedPersonCarried() {
        return closedPersonCarried;
    }

    /** Each pool member's cut fixed when it was closed, by member key; empty while open. */
    public Map<String, BigDecimal> getClosedCuts() {
        return closedCuts;
    }

    /** Each person's opening balance for the period, by person id; a person missing here has none. */
    public Map<Long, BigDecimal> getOpenings() {
        return openings;
    }

    /** Add an amount to a person's opening balance for the period. */
    public void addOpening(long personId, BigDecimal amount) {
        openings.merge(personId, amount, BigDecimal::add);
    }

    /** Close the period, fixing each person's due-total and carried figure for it, and its own as the sum of
     *  their due-totals. */
    public void close(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried,
            Map<String, BigDecimal> cuts) {
        fix(personTotals, personCarried, cuts);
        this.closed = true;
        this.softClosed = false;
    }

    /** Soft-close the period, fixing its figures as a close does while its claims can still change. */
    public void softClose(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried,
            Map<String, BigDecimal> cuts) {
        fix(personTotals, personCarried, cuts);
        this.softClosed = true;
    }

    private void fix(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried,
            Map<String, BigDecimal> cuts) {
        this.closedCuts.clear();
        this.closedCuts.putAll(cuts);
        this.closedPersonTotals.clear();
        this.closedPersonTotals.putAll(personTotals);
        this.closedPersonCarried.clear();
        this.closedPersonCarried.putAll(personCarried);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Count one person's fixed due-total, carried figure and opening balance for the period as another's, added to theirs. */
    public void moveClosedTotal(long fromId, long intoId) {
        BigDecimal moving = closedPersonTotals.remove(fromId);
        if (moving != null) {
            closedPersonTotals.merge(intoId, moving, BigDecimal::add);
        }
        BigDecimal carried = closedPersonCarried.remove(fromId);
        if (carried != null) {
            closedPersonCarried.merge(intoId, carried, BigDecimal::add);
        }
        BigDecimal opening = openings.remove(fromId);
        if (opening != null) {
            openings.merge(intoId, opening, BigDecimal::add);
        }
    }

    /** Drop a person's fixed due-total, carried figure and opening balance for the period, leaving its due-total as it was fixed. */
    public void dropClosedTotal(long personId) {
        closedPersonTotals.remove(personId);
        closedPersonCarried.remove(personId);
        openings.remove(personId);
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.closedPersonTotals.clear();
        this.closedPersonCarried.clear();
        this.closedCuts.clear();
    }

    /** Whether a date falls in this period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(fromDate) && !date.isAfter(toDate);
    }

    /** Whether this period shares a day with one from one date to another. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !fromDate.isAfter(to) && !from.isAfter(toDate);
    }
}
